// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep amount in a reasonable wide payable range (nonzero)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1e26); // up to very large, but bounded

        // Arrange: give depositor some ETH
        vm.deal(depositor, amount);

        // Record previous balance in contract for this depositor
        uint256 prev = c.balances(depositor);

        // Act: have depositor call Deposit with amount
        vm.prank(depositor);
        c.Deposit{value: amount}();

        // Exactly one assertion: the contract's balances should equal prev + amount
        // This is true in the reference (accumulating deposit) for all inputs, but
        // the mutant that overwrites balances with msg.value will fail when
        // prev != 0 and prev + amount != amount (i.e., prev != 0).
        assertTrue(c.balances(depositor) == prev + amount);
    }
}

