pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz two addresses and two amounts. The property:
    // If an address b makes a deposit w, then a distinct address a makes a deposit v,
    // the reference contract must keep balances(b) equal to its previous recorded balance (w).
    // The mutant that overwrites balances[msg.sender] = msg.value can, in some implementations
    // or via mistakes, corrupt other keys; this test checks that b's balance remains unchanged.
    function testFuzz_property(address a, address b, uint256 w, uint256 v) public {
        // wide assumptions: distinct actors, nonzero deposits within reasonable gasable bounds
        vm.assume(a != address(0));
        vm.assume(b != address(0));
        vm.assume(a != b);
        // keep amounts in a sensible range to avoid trivial zero behavior
        w = bound(w, 1, 1 ether);
        v = bound(v, 1, 1 ether);

        // fund both actors
        vm.deal(a, 2 ether);
        vm.deal(b, 2 ether);

        // b deposits w
        vm.prank(b);
        c.Deposit{value: w}();

        // record b's balance after its deposit
        uint256 bAfter = c.balances(b);

        // a deposits v
        vm.prank(a);
        c.Deposit{value: v}();

        // Exactly one assertion: b's recorded balance must remain equal to its previous value
        // Reference preserves other accounts' balances; mutant that overwrites storage may change b's slot
        assertTrue(c.balances(b) == bAfter);
    }
}

