pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor address and two deposit amounts
    function testFuzz_property(address depositor, uint256 v1, uint256 v2) public {
        // keep depositor as an EOA and non-zero amounts reasonably bounded
        vm.assume(depositor != address(0));
        v1 = bound(v1, 0, 1 ether * 1000); // keep within reasonable gas/ETH limits
        v2 = bound(v2, 0, 1 ether * 1000);

        // We need v1 != 0 to create a difference when mutant overwrites instead of accumulating.
        // But allow v2==0 (a zero second deposit should leave balance unchanged in both versions).
        vm.assume(v1 != 0);

        // Fund depositor so they can send v1 and v2
        vm.deal(depositor, v1 + v2);

        // First deposit
        vm.prank(depositor);
        c.Deposit{value: v1}();

        // Record balance after first deposit via public getter
        uint256 after1 = c.balances(depositor);

        // Second deposit
        vm.prank(depositor);
        c.Deposit{value: v2}();

        // Single assertion: after two sequential deposits by the same depositor, the increment from after1
        // to the new recorded balance equals v2 (i.e., new_balance == after1 + v2). The reference C implements
        // accumulation so this holds for all admissible inputs; the mutant that overwrites balance with msg.value
        // will make new_balance == v2 instead, causing the assertion to fail for cases where after1 != 0.
        uint256 after2 = c.balances(depositor);
        assertTrue(after2 == after1 + v2);
    }
}

