import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: depositor contract address is created here, amount is fuzzed
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // keep amount in a wide but reasonable range and non-zero so Deposit has observable effect
        amount = bound(amount, 1 wei, 1e30); // wide bound

        // deploy a simple contract that can receive Ether (will accept) so msg.sender is a contract
        Depositor d = new Depositor();

        // fund the depositor so it can call Deposit with the fuzzed amount
        vm.deal(address(d), amount);

        // record balance before
        uint256 before = c.balances(address(d));

        // have the depositor call into c.Deposit() sending `amount`
        d.callDeposit{value: amount}(address(c));

        // record after
        uint256 after = c.balances(address(d));

        // The general rule: the correct contract increments the depositor's stored balance by exactly amount
        // So delta == amount. The mutant double-credits and for some inputs (any amount) delta == 2*amount
        // Assert the reference property (delta == amount). This holds for the reference for ALL admissible inputs
        // but fails for the mutant when it double-credits.
        assertTrue(after - before == amount);
    }
}

// A minimal depositor contract that simply forwards Ether to C.Deposit
contract Depositor {
    // allow deposits
    receive() external payable {}

    function callDeposit(address caddr) external payable {
        C(caddr).Deposit{value: msg.value}();
    }
}

