// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters:
    // - depositor: address that will deposit
    // - attackerInitial: initial balance to set for depositor in contract storage before deposit
    // - depositAmt: amount to deposit
    // We let the fuzzer choose these; we will bound amounts to sane ranges.
    function testFuzz_property(address depositor, uint256 attackerInitial, uint256 depositAmt) public {
        // keep depositor non-zero
        vm.assume(depositor != address(0));
        // bound amounts to less than 1e20 to avoid overflow and keep gas reasonable
        attackerInitial = bound(attackerInitial, 0, 1e20);
        depositAmt = bound(depositAmt, 1, 1e18); // at least 1 wei, up to 1 ether

        // Deploy a malicious LogFile that re-enters C during logging to exploit logging-before-update mutant.
        // The attacker will be the depositor; we deploy the Attacker contract and set it as the Log in C.
        Attacker att = new Attacker(address(c));

        // Set the contract's Log to our attacker contract before initialization
        // C.SetLogFile is public; call it from this test (test contract) to set attacker as Log.
        c.SetLogFile(address(att));

        // Ensure depositor has ETH to send
        vm.deal(depositor, depositAmt + 1 ether);

        // Preload the contract's balances[depositor] to attackerInitial by performing a pre-deposit from depositor
        // We do this using a direct deposit call with that amount
        if (attackerInitial > 0) {
            vm.prank(depositor);
            c.Deposit{value: attackerInitial}();
        }

        // Record balance mapping for depositor before performing the fuzz deposit
        uint256 before = c.balances(depositor);

        // Configure attacker to target `depositor` when Log.AddMessage is invoked
        att.setTarget(depositor);

        // Now perform the fuzzed deposit from depositor of depositAmt; the Attacker's fallback will try to reenter
        vm.prank(depositor);
        // wrap call in try/catch because some variants might revert
        bool ok;
        try c.Deposit{value: depositAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After Deposit returns, the correct contract guarantees that balances[depositor] == before + depositAmt
        // The mutant that logs first allows attacker reentrancy to observe old balance and potentially change mapping,
        // causing this equality to fail for some inputs. We assert the universal property here.
        assertTrue(c.balances(depositor) == before + depositAmt);
    }
}

// Minimal attacker that acts as the LogFile and re-enters C during AddMessage.
contract Attacker {
    address targetC;
    address victim; // the depositor whose balance will be re-deposited/collected during reentry

    constructor(address _c) {
        targetC = _c;
    }

    function setTarget(address _v) public {
        victim = _v;
    }

    // This mimics the LogFile.AddMessage signature. It will try to re-enter C by calling Collect on the victim
    // if possible, or perform another Deposit to manipulate state. We keep it simple: call Collect on victim
    // to attempt to trigger behavior differences in the mutant that logs before update.
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // attempt to call Collect on C as the victim (reenter)
        // We use a low-level call so we don't revert test if it fails.
        (bool s, ) = targetC.call(abi.encodeWithSignature("Collect(uint256)", _val));
        // ignore result
        s;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and amount (must be >0 and within balance provided)
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor as a real account and amount in a reasonable range
        vm.assume(depositor != address(0));
        uint256 boundedAmt = bound(amt, 1, 1 ether);

        // Deploy a malicious Log that will re-enter C.Deposit during AddMessage
        ReentrantLog attacker = new ReentrantLog(address(c));

        // set the contract's Log to the attacker address
        c.SetLogFile(address(attacker));

        // fund depositor so they can send boundedAmt
        vm.deal(depositor, boundedAmt);

        // record prior balance according to c for depositor
        uint256 prior = c.balances(depositor);

        // Have depositor perform Deposit which will call into attacker.AddMessage,
        // which re-enters Deposit to try to exploit ordering difference.
        vm.prank(depositor);
        // call Deposit with value boundedAmt
        (bool ok, ) = address(c).call{value: boundedAmt}(abi.encodeWithSignature("Deposit()"));
        // After Deposit returns, the invariant for the reference is:
        // c.balances(depositor) == prior + boundedAmt
        // Mutant that logs first can be exploited by reentrant AddMessage to make this fail.
        assertTrue(c.balances(depositor) == prior + boundedAmt);
    }
}

// Minimal adversarial helper that acts as the LogFile and re-enters C during AddMessage
contract ReentrantLog {
    C target;
    bool reentered;
    constructor(address _target) {
        target = C(_target);
        reentered = false;
    }

    // Match signature AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // On first call, re-enter target.Deposit() to trigger reentrancy during logging
        if (!reentered) {
            reentered = true;
            // Attempt to re-enter Deposit by sending 0 value (could also send value if payable),
            // but re-entering any path that invokes logging before balance update will observe old balances.
            // Call Deposit via low-level to avoid type restrictions; no value is needed for this re-entry.
            // Use try/catch to avoid bubbling reverts into the attacker itself.
            try target.Deposit() {
            } catch {
            }
        }
        // Record nothing — just a malicious observer
    }
}

